export default (got) => {
    return {
        async status() {
            return await got.get(`hub/status`).json();
        },
        async checkFirmwareUpdate() {
            await got.put(`hub/ota/check`).json();
        },
        async installFirmwareUpdate() {
            await got.put(`hub/ota/update`).json();
        },
    };
};
